  }
  .kpi-card .kpi-detail {
    font-size: 12px;
    color: var(--color-text-secondary);
    margin-top: 4px;
  }

  /* Sections */
  .section {
    margin-bottom: 48px;
    page-break-inside: avoid;
  }
  .section-header {
    display: flex;
    align-items: center;
    gap: 12px;
    margin-bottom: 20px;
    padding-bottom: 12px;
    border-bottom: 1px solid var(--color-border);
  }
