  }
  .section h2 {
    font-size: 20px;
    font-weight: 700;
    color: var(--color-text);
  }
  .section p {
    margin-bottom: 16px;
    color: var(--color-text);
  }

  /* Charts */
  .chart-container {
    background: var(--color-surface);
    border: 1px solid var(--color-border);
    border-radius: 8px;
    padding: 24px;
    margin: 20px 0;
    position: relative;
  }
  .chart-container canvas {
    max-height: 400px;
  }
  .chart-title {
    font-size: 14px;
    font-weight: 600;
    color: var(--color-text);
    margin-bottom: 12px;
  }

  /* Tables */
  .data-table {
    width: 100%;
    border-collapse: collapse;
