    gap: 20px;
  }
  @media (max-width: 800px) { .two-col { grid-template-columns: 1fr; } }

  .insight-callout {
    background: #EFF6FF;
    border: 1px solid #BFDBFE;
    border-radius: 8px;
    padding: 16px;
    margin: 16px 0;
    font-size: 14px;
  }
  .insight-callout strong { color: var(--color-accent); }

  .bar-inline {
    display: inline-block;
    height: 14px;
    border-radius: 3px;
    vertical-align: middle;
    margin-right: 6px;
  }

  /* Footer */
  .report-footer {
    margin-top: 48px;
    padding-top: 20px;
    border-top: 1px solid var(--color-border);
    font-size: 12px;
    color: var(--color-text-secondary);
    text-align: center;
  }

  /* Numbered findings list */
  .findings-list { list-style: none; counter-reset: finding; }
  .findings-list li {
    counter-increment: finding;
    padding: 16px 20px;
    margin-bottom: 12px;
    background: var(--color-surface);
    border: 1px solid var(--color-border);
    border-radius: 8px;
    position: relative;
    padding-left: 56px;
  }
  .findings-list li::before {
    content: counter(finding);
    position: absolute;
    left: 16px;
    top: 16px;
    background: var(--color-accent);
    color: white;
    width: 28px;
    height: 28px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: 700;
    font-size: 13px;
  }
  .findings-list li strong { display: block; margin-bottom: 4px; }
  .findings-list li p { margin: 0; font-size: 14px; color: var(--color-text-secondary); }

  .tag {
    display: inline-block;
    padding: 2px 8px;
    border-radius: 4px;
    font-size: 11px;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.3px;
  }
  .tag-high { background: #FEE2E2; color: #991B1B; }
  .tag-mid { background: #FEF3C7; color: #92400E; }
  .tag-low { background: #DCFCE7; color: #166534; }
</style>
</head>
<body>
<div class="report-container">

<!-- HEADER -->
<header class="report-header">
  <h1>Global Fuel Price Trends &amp; Policy Impact Analysis</h1>
  <div class="subtitle">A data-driven examination of retail fuel prices across 84 countries, Brent Crude transmission, and the efficacy of subsidy and tax policy (2020&ndash;2026)</div>
  <div class="meta">
    <span><strong>Period:</strong>&nbsp;Jan 2020 &ndash; Apr 2026</span>
    <span><strong>Coverage:</strong>&nbsp;84 Countries &middot; 7 Regions</span>
    <span><strong>Observations:</strong>&nbsp;27,468 weekly records</span>
    <span><strong>Prepared:</strong>&nbsp;April 2026</span>
  </div>
</header>

<!-- KPI SUMMARY -->
<div class="kpi-grid">
  <div class="kpi-card">
    <div class="kpi-label">Avg Retail Petrol Price</div>
    <div class="kpi-value">$2.28<span style="font-size:16px">/L</span></div>
    <div class="kpi-detail">Range: $0.01 &ndash; $6.78 per liter</div>
  </div>
  <div class="kpi-card">
    <div class="kpi-label">Brent&ndash;Retail Correlation</div>
    <div class="kpi-value">r = 1.00</div>
    <div class="kpi-detail">Near-perfect weekly co-movement</div>
  </div>
  <div class="kpi-card">
    <div class="kpi-label">Subsidy Dampening (High)</div>
    <div class="kpi-value">-79.5%</div>
    <div class="kpi-detail">High-subsidy vs. Low-subsidy retail price</div>
  </div>
  <div class="kpi-card">
    <div class="kpi-label">Regional Price Spread</div>
    <div class="kpi-value">$2.48<span style="font-size:16px">/L</span></div>
    <div class="kpi-detail">Europe ($3.70) vs. Middle East ($1.23)</div>
  </div>
  <div class="kpi-card">
    <div class="kpi-label">Tax-to-Price Ratio</div>
    <div class="kpi-value">34.7%</div>
    <div class="kpi-detail">High-income avg | Middle: 21.1% | Low: 22.9%</div>
  </div>
</div>

<!-- SECTION 1: GLOBAL OVERVIEW -->
<section class="section" id="global-overview">
  <div class="section-header">
    <div class="section-number">1</div>
    <h2>Global Fuel Price Overview</h2>
  </div>

  <p>Between January 2020 and April 2026, global retail fuel prices underwent dramatic shifts driven by pandemic-era demand destruction, post-recovery supply constraints, and the 2022 energy crisis. The dataset spans 84 countries across 7 regions with 327 weekly observations per country.</p>

  <table class="data-table">
    <thead>
      <tr><th>Fuel Type</th><th class="right">Mean (USD/L)</th><th class="right">2020 Avg</th><th class="right">2022 Peak</th><th class="right">2026 Latest</th><th class="right">Period Change</th></tr>
    </thead>
    <tbody>
      <tr><td>Petrol (Gasoline)</td><td class="right">$2.282</td><td class="right">$1.485</td><td class="right">$2.505</td><td class="right">$2.647</td><td class="right">+78.2%</td></tr>
      <tr><td>Diesel</td><td class="right">$2.134</td><td class="right">$1.389</td><td class="right">$2.342</td><td class="right">$2.474</td><td class="right">+78.1%</td></tr>
      <tr><td>LPG</td><td class="right">$1.711</td><td class="right">$1.114</td><td class="right">$1.879</td><td class="right">$1.985</td><td class="right">+78.2%</td></tr>
      <tr><td style="color:var(--color-brent);">Brent Crude (USD/bbl)</td><td class="right">$106.69</td><td class="right">$69.44</td><td class="right">$117.12</td><td class="right">$123.75</td><td class="right">+78.2%</td></tr>
    </tbody>
  </table>

  <div class="insight-callout">
    <strong>Key observation:</strong> All three retail fuel types tracked Brent Crude with near-identical percentage changes over the period, rising approximately 78% from 2020 baselines. The mean retail petrol price of <strong>$2.28/L</strong> masks enormous country-level dispersion &mdash; from $0.01/L in Venezuela to $6.78/L in Hong Kong.
  </div>

  <div class="chart-container">
    <div class="chart-title">Brent Crude Oil Price Trajectory (2020&ndash;2026)</div>
    <canvas id="chart-brent-overview"></canvas>
  </div>
</section>

<!-- SECTION 2: TEMPORAL TRENDS -->
<section class="section" id="temporal-trends">
  <div class="section-header">
    <div class="section-number">2</div>
    <h2>Temporal Price Trends &amp; Volatility</h2>
  </div>

  <p>The 2020&ndash;2026 window captures three distinct market regimes: the COVID-19 demand shock (2020), the post-pandemic surge and 2022 energy crisis, and subsequent stabilization. Brent Crude fell to $47.97/bbl in late April 2020, then climbed steadily to peak near $130/bbl, a level it reached by late 2024 and maintained through early 2026.</p>

  <div class="chart-container">
    <div class="chart-title">Weekly Retail Fuel Prices vs. Brent Crude (Global Average)</div>
    <canvas id="chart-temporal-main"></canvas>
  </div>

  <div class="two-col">
    <div>
      <h3 style="font-size:15px; margin-bottom:12px;">Yearly Average Prices</h3>
      <table class="data-table">
        <thead><tr><th>Year</th><th class="right">Petrol</th><th class="right">Diesel</th><th class="right">LPG</th><th class="right">Brent</th></tr></thead>
        <tbody>
          <tr><td>2020</td><td class="right">$1.485</td><td class="right">$1.389</td><td class="right">$1.114</td><td class="right">$69.44</td></tr>
          <tr><td>2021</td><td class="right">$2.280</td><td class="right">$2.131</td><td class="right">$1.710</td><td class="right">$106.59</td></tr>
          <tr><td>2022</td><td class="right">$2.505</td><td class="right">$2.342</td><td class="right">$1.879</td><td class="right">$117.12</td></tr>
